# Generated by Descant: acceptance tests.

# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::LegacyAuditConversion do
  # "Keep its company, author, action, original `created_at` and change values (before and after from `audited_changes`), and set `entry_created_at` from the entry."
  it "converts create and update audits keeping company, author, action, original created_at and change values" do
    entry_created_at = Time.utc(2026, 1, 1, 9, 0, 0)
    created = Time.utc(2026, 1, 1, 9, 0, 1)
    updated = Time.utc(2026, 2, 3, 4, 5, 6)
    entries_by_id = { 501 => { "id" => 501, "company_id" => 3, "created_at" => entry_created_at } }
    audits = [
      { id: 1, action: "create", associated_type: "Company", associated_id: 3, auditable_id: 501,
        user_type: "User", user_id: 5, username: nil, audited_changes: { "note" => "first" }, created_at: created },
      { id: 2, action: "update", associated_type: "Company", associated_id: 3, auditable_id: 501,
        user_type: "User", user_id: 6, username: nil, audited_changes: { "note" => ["first", "second"] }, created_at: updated }
    ]

    result = described_class.convert(audits:, entries_by_id:)

    expect(result[:refusals]).to be_empty
    create_row, update_row = result[:rows].sort_by { |row| row["id"] }
    expect(create_row).to include(
      "id" => 1, "company_id" => 3, "entry_id" => 501, "actor_type" => "user", "actor_id" => 5,
      "action" => "create", "before" => nil, "after" => { "note" => "first" },
      "created_at" => created, "entry_created_at" => entry_created_at
    )
    expect(update_row).to include(
      "id" => 2, "company_id" => 3, "entry_id" => 501, "actor_type" => "user", "actor_id" => 6,
      "action" => "update", "before" => { "note" => "first" }, "after" => { "note" => "second" },
      "created_at" => updated, "entry_created_at" => entry_created_at
    )
  end
end
